def make_normalizer(mode):
    if mode == 'digits':
        def norm(raw):
            return ''.join(c for c in raw if c.isdigit())
        return norm
    if mode == 'lower':
        def norm(raw):
            return raw.strip().lower()
        return norm
    raise ValueError('mode desconocido')
